"""fstdd ci — Generate CI/CD config files and run deterministic failure checks."""
import argparse
import sys
import re
import json
import os
from pathlib import Path
from datetime import datetime


# Registry of check functions: each returns (status, message)
# status: "PASS" | "FAIL" | "WARN" | "SKIP"
CHECKS = []


def _register_check(fn):
    CHECKS.append(fn)
    return fn



GITHUB_WORKFLOW_TEMPLATE = """\
# STDD Quality Gate — Auto-generated by `fstdd ci init`
# Version: {version}
# Generated: {date}

name: STDD Quality Gate

on:
  push:
    branches: [main, master, develop]
  pull_request:
    branches: [main, master]

jobs:
  stdd-quality:
    runs-on: ubuntu-latest
    # For Windows projects, change to: runs-on: windows-latest
    # and add 'shell: bash' to each step's run block
    steps:
      - uses: actions/checkout@v4

      - name: Setup Python
        uses: actions/setup-python@v5
        with:
          python-version: '{python_version}'

      - name: Install dependencies
        run: |
          python -m pip install --upgrade pip
          pip install -r requirements.txt
          pip install pytest pytest-cov ruff

      - name: STDD Validate
        run: python bin/fstdd validate

      - name: Run Tests with Coverage
        run: {test_command}

      - name: STDD Diff Check
        run: python bin/fstdd diff

      - name: Lint Check
        run: {lint_command}

      - name: Type Check
        run: {typecheck_command}

      - name: STDD Failure Check
        run: python bin/fstdd ci check-failures
"""

PRECOMMIT_TEMPLATE = """\
# STDD Pre-commit Hook — Auto-generated by `fstdd ci init`
# Version: {version}
# Generated: {date}

repos:
  - repo: local
    hooks:
      - id: stdd-validate
        name: STDD Validate
        entry: python bin/fstdd validate
        language: system
        pass_filenames: false
        stages: [commit]

      - id: stdd-lint
        name: STDD Lint
        entry: {lint_command}
        language: system
        pass_filenames: false
        types: [python]
        stages: [commit]
"""

PR_COMMENT_TEMPLATE = """\
## STDD Quality Gate Results

| Check | Status | Details |
|-------|--------|---------|
| Validate | {{ validate }} | Structure & spec format check |
| Tests | {{ tests }} | {{ test_summary }} |
| Coverage | {{ coverage }}% | Target: {{ coverage_target }}% |
| Diff | {{ diff }} | Spec ↔ Test ↔ Code traceability |
| Lint | {{ lint }} | Code style check |
| Failure Check | {{ failures }} | 11 failure modes (deterministic subset) |

{{ failure_details }}

---
📋 [Full Test Report]({{ test_report_url }}) · 📝 [Design Adjustments]({{ adjustments_url }})
"""


def _read_quality_config(project_root: Path) -> dict:
    """Read quality.yaml config."""
    from ..utils import read_config
    return read_config(project_root)


def _generate_workflow(project_root: Path, config: dict, dry_run: bool = False) -> str:
    ci_cfg = config.get("ci", {}).get("github_actions", {})
    python_version = ci_cfg.get("python_version", config.get("project", {}).get("python_version", "3.11"))
    test_cmd = ci_cfg.get("test_command", "pytest tests/ --cov=app --cov-report=xml --cov-report=term")
    lint_cmd = ci_cfg.get("lint_command", "ruff check app/ tests/")
    typecheck_cmd = ci_cfg.get("typecheck_command", "mypy app/")

    content = GITHUB_WORKFLOW_TEMPLATE.format(
        version="2.4",
        date=datetime.now().strftime("%Y-%m-%d"),
        python_version=python_version,
        test_command=test_cmd,
        lint_command=lint_cmd,
        typecheck_command=typecheck_cmd,
    )

    workflow_dir = project_root / ".github" / "workflows"
    workflow_path = workflow_dir / "stdd-quality.yml"

    if dry_run:
        print(f"\n  [DRY-RUN] 将创建: {workflow_path}")
        print("  ──────────────────────────────────────")
        print(content)
        return content

    workflow_dir.mkdir(parents=True, exist_ok=True)
    workflow_path.write_text(content, encoding="utf-8")
    print(f" 已创建: {workflow_path}")
    return content


def _generate_precommit(project_root: Path, config: dict, dry_run: bool = False) -> str:
    lint_cmd = config.get("quality", {}).get("lint", "ruff check app/ tests/")

    content = PRECOMMIT_TEMPLATE.format(
        version="2.4",
        date=datetime.now().strftime("%Y-%m-%d"),
        lint_command=lint_cmd,
    )

    precommit_path = project_root / ".pre-commit-config.yaml"

    if dry_run:
        print(f"\n  [DRY-RUN] 将创建: {precommit_path}")
        print("  ──────────────────────────────────────")
        print(content)
        return content

    if precommit_path.exists():
        existing = precommit_path.read_text(encoding="utf-8")
        if "STDD" in existing:
            print("  检测到已有 STDD pre-commit hook，跳过生成（避免覆盖现有配置）。")
            print("  如需重新生成，请先手动删除 .pre-commit-config.yaml 中的 STDD 段。")
            return content

        print("  检测到已有 .pre-commit-config.yaml，追加 STDD hook 段...")
        with open(precommit_path, "a", encoding="utf-8") as f:
            f.write("\n" + content)
        print(f" 已追加到: {precommit_path}")
        return content

    precommit_path.write_text(content, encoding="utf-8")
    print(f" 已创建: {precommit_path}")
    return content


def _generate_pr_template(project_root: Path, config: dict, dry_run: bool = False) -> str:
    github_dir = project_root / ".github"
    pr_path = github_dir / "stdd-pr-comment.md"

    if dry_run:
        print(f"\n  [DRY-RUN] 将创建: {pr_path}")
        print("  ──────────────────────────────────────")
        print(PR_COMMENT_TEMPLATE)
        return PR_COMMENT_TEMPLATE

    github_dir.mkdir(parents=True, exist_ok=True)
    pr_path.write_text(PR_COMMENT_TEMPLATE, encoding="utf-8")
    print(f" 已创建: {pr_path}")
    return PR_COMMENT_TEMPLATE


def _cmd_generate(args: argparse.Namespace, project_root: Path, config: dict) -> None:
    target = args.target
    dry_run = getattr(args, "dry_run", False)

    if target == "workflow":
        _generate_workflow(project_root, config, dry_run)
    elif target == "pre-commit":
        _generate_precommit(project_root, config, dry_run)
    elif target == "pr-template":
        _generate_pr_template(project_root, config, dry_run)
    else:
        print(f" 未知目标: {target}. 可用: workflow, pre-commit, pr-template")


def _cmd_init(args: argparse.Namespace, project_root: Path, config: dict) -> None:
    dry_run = getattr(args, "dry_run", False)
    print()
    if dry_run:
        print(" [DRY-RUN 模式] 预览将要创建的文件:\n")

    _generate_workflow(project_root, config, dry_run)
    _generate_precommit(project_root, config, dry_run)
    _generate_pr_template(project_root, config, dry_run)

    if dry_run:
        print("\n [DRY-RUN] 以上为预览，未实际创建任何文件。")
        print(" 去掉 --dry-run 以实际生成。")
    else:
        print()
        print(" STDD CI/CD 配置生成完成！")
        print(" 下一步：")
        print("   git add .github/ .pre-commit-config.yaml")
        print("   git commit -m 'chore: add STDD quality gate CI'")


def _cmd_check_failures(args: argparse.Namespace, project_root: Path) -> None:
    from ..finder import find_change_dir

    change_dir = find_change_dir(getattr(args, "name", None), project_root, include_archive=True)
    if change_dir is None:
        print(f" 找不到 change: {getattr(args, 'name', None) or '(无)'}")
        sys.exit(1)

    results = []
    for check_fn in CHECKS:
        status, message = check_fn(change_dir, project_root)
        results.append((status, message))

    passed = [m for s, m in results if s == "PASS"]
    warnings = [m for s, m in results if s == "WARN"]
    skipped = [m for s, m in results if s == "SKIP"]
    errors = [m for s, m in results if s == "FAIL"]

    print()
    print("  STDD 失败模式检查结果 (CLI 确定性子集)")
    print(f"  {'─' * 50}")
    print(f"  ✅ 通过: {len(passed)}")
    print(f"  ⚠ 警告: {len(warnings)}")
    print(f"  ⏭ 跳过: {len(skipped)}")
    print(f"  ❌ 错误: {len(errors)}")

    if passed:
        print("\n  通过项:")
        for p in passed:
            print(f"    ✓ {p}")
    if warnings:
        print("\n  警告项:")
        for w in warnings:
            print(f"    ⚠ {w}")
    if skipped:
        print("\n  跳过项:")
        for s in skipped:
            print(f"    → {s}")
    if errors:
        print("\n  错误项:")
        for e in errors:
            print(f"    ✗ {e}")

    total = len(results)
    automated = len([s for s, _, in results if s != "SKIP"])
    print(f"\n  ──────────────────────────────────────")
    print(f"  自动化检查覆盖: {automated}/{total} 项")
    print(f"  完整 14 类检查（含语义分析）请在 BUILD 质量验证阶段执行")
    print()

    if errors:
        sys.exit(1)


# ── Registered check functions ────────────────────────────

@_register_check
def check_files_exist(change_dir: Path, _project_root: Path) -> tuple[str, str]:
    """(a) Check required files exist."""
    missing = []
    for f in ["proposal.md", "design.md", "test-plan.md", ".fstdd.yaml"]:
        if not (change_dir / f).exists():
            missing.append(f)
    if missing:
        return ("FAIL", f"(a) 缺失文件: {', '.join(missing)}")
    specs_dir = change_dir / "specs"
    if specs_dir.exists() and any(specs_dir.rglob("*.md")):
        return ("PASS", "(a) 所有必需文件存在 + Spec 文件存在")
    return ("WARN", "(a) 必需文件存在，但 specs 目录为空")


# TC-ID 的**定义点**：TC-ID 出现在表格行的「ID 槽位」。
#
# 为什么按定义点而非全文出现次数：项目约定在「案例标题 / 优先顺序 / 回归矩阵 / 证据表」
# 多处**引用**同一 ID，把引用当重复会大面积误判 —— 实测 42 份既有 test-plan 中
# **26 份（62%）**被判 FAIL，门禁的 ❌ 因此变成噪声，真正的 ID 冲突反被淹没。
# 该现象此前被记为「已知假阳性」（EXP-2026-0016），本次真正修掉。
#
# ⚠️ 形态 B **只在形态 A 一个都没抽到时才启用**（见 `_tcid_definition_points`）：
# 「TC-ID 作首列」的表格既可能是定义表，也可能是 TC↔测试函数 的**映射表**
# （实测 `.fstdd/archive/2026-09-25-guard-phase-path-scope/test-plan.md` 就有这种映射表，
# 若两种形态同时计入会把「1 个定义 + 1 行映射」误判为重复定义）。
_TC_DEFINITION_RE_A = re.compile(
    r"^\|\s*\*{0,2}ID\*{0,2}\s*\|\s*`?\*{0,2}(TC-[A-Z]+-\d{3})\*{0,2}`?\s*\|",
    re.MULTILINE,
)
_TC_DEFINITION_RE_B = re.compile(
    r"^\|\s*`?\*{0,2}(TC-[A-Z]+-\d{3})\*{0,2}`?\s*\|",
    re.MULTILINE,
)
_TC_ANY_RE = re.compile(r"(TC-[A-Z]+-\d{3})")


def _tcid_definition_points(content: str) -> list:
    """抽取全部 TC-ID **定义点**。

    优先级：形态 A（`| **ID** | TC-… |`，本项目现行约定）→ 形态 B（ID 作首列）→ 空。
    **不做并集** —— 形态 B 与「TC↔测试函数映射表」在文本上不可区分，并集会产生假重复。
    """
    a = _TC_DEFINITION_RE_A.findall(content)
    if a:
        return a
    return _TC_DEFINITION_RE_B.findall(content)


@_register_check
def check_tcid_unique(change_dir: Path, _project_root: Path) -> tuple[str, str]:
    """(d) Check TC-ID uniqueness in test-plan.md（按**定义点**判定）。

    同一 TC-ID 出现在 **≥2 个定义点**才判 FAIL；纯引用不计。

    兼容：若 test-plan 不含任何标准定义行（旧格式，如裸文本罗列），
    退回「全文出现次数」判定 —— 此时无法区分定义与引用，保守沿用旧行为。
    """
    test_plan = change_dir / "test-plan.md"
    if not test_plan.exists():
        return ("SKIP", "(d) test-plan.md 不存在，跳过 TC-ID 检查")
    content = test_plan.read_text(encoding="utf-8")

    definitions = _tcid_definition_points(content)
    if definitions:
        ids, basis = definitions, "定义点"
    else:
        ids, basis = _TC_ANY_RE.findall(content), "全文（无标准定义行，回退）"
        if not ids:
            return ("WARN", "(d) 未找到 TC-ID")

    counts: dict = {}
    for i in ids:
        counts[i] = counts.get(i, 0) + 1
    duplicates = sorted(k for k, v in counts.items() if v > 1)
    if duplicates:
        return ("FAIL", f"(d) 重复 TC-ID: {duplicates}")
    return ("PASS", f"(d) TC-ID 唯一 ({len(counts)} 个，按{basis})")


@_register_check
def check_shall_keyword(change_dir: Path, _project_root: Path) -> tuple[str, str]:
    """(f) Check THEN statements contain SHALL keyword."""
    specs_dir = change_dir / "specs"
    if not specs_dir.exists():
        return ("SKIP", "(f) specs 目录不存在，跳过 SHALL 检查")
    spec_files = list(specs_dir.rglob("*.md"))
    if not spec_files:
        return ("SKIP", "(f) 无 spec 文件")
    issues = []
    for sf in spec_files:
        content = sf.read_text(encoding="utf-8")
        then_lines = re.findall(r"\*\*THEN\*\*\s*(.+?)(?:\n|$)", content)
        no_shall = [t for t in then_lines if "SHALL" not in t]
        if no_shall:
            issues.append(f"{sf.name}: {len(no_shall)} 处缺少 SHALL")
    if issues:
        return ("WARN", f"(f) SHALL 缺失: {', '.join(issues)}")
    return ("PASS", "(f) 所有 THEN 含 SHALL")


@_register_check
def check_and_count(change_dir: Path, _project_root: Path) -> tuple[str, str]:
    """(g) Check AND count per scenario."""
    specs_dir = change_dir / "specs"
    if not specs_dir.exists():
        return ("SKIP", "(g) specs 目录不存在")
    spec_files = list(specs_dir.rglob("*.md"))
    if not spec_files:
        return ("SKIP", "(g) 无 spec 文件")
    issues = []
    for sf in spec_files:
        content = sf.read_text(encoding="utf-8")
        and_count = len(re.findall(r"\*\*AND\*\*", content))
        if and_count > 5:
            issues.append(f"{sf.name}: AND 数量 {and_count}")
    if issues:
        return ("WARN", f"(g) AND 超限: {', '.join(issues)}")
    return ("PASS", "(g) AND 数量正常")


# ── 范围锁（anti-drift-gates，2026-10-28）────────────────────
# 豁免白名单：这些路径即使不在 scope.paths 内也不算蔓延（属正常流程产出物）。
# 集中定义，不散落到各判据里 —— 否则新增一类产出物要改多处。
SCOPE_EXEMPT_PREFIXES = (
    ".fstdd/changes/",      # 本 change 产出物（proposal / spec / test-plan / report）
    ".fstdd/archive/",      # 归档产出物
    ".fstdd/experiences/",  # BUILD C5 要求更新既有经验条目
    ".fstdd/specs/",        # DELIVER 合并的全局 spec
    ".fstdd/code-structure/",
    "docs/",                # 文档
)
SCOPE_EXEMPT_EXACT = {
    "README.md", "CHANGELOG.md", "NOTICE.md", ".gitignore", ".gitattributes",
    ".fstdd/version.yaml", ".fstdd/config.d/project.yaml", ".fstdd/backlog.md",
}

# scope 过宽的判据：命中这些根目录等于「声明了全仓」，范围锁形同虚设
_BROAD_SCOPE_ROOTS = ("upstream", "tests", "tools", "src", "app", "skills")


def _load_baseline_sha(change_dir: Path):
    """从 change 的 .fstdd.yaml 读 baseline.base_git_sha；读不到返回 None。"""
    state_file = change_dir / ".fstdd.yaml"
    if not state_file.exists():
        return None
    try:
        import yaml as _yaml
        data = _yaml.safe_load(state_file.read_text(encoding="utf-8")) or {}
    except (OSError, UnicodeDecodeError, Exception):  # noqa: BLE001
        return None
    baseline = data.get("baseline") if isinstance(data, dict) else None
    if not isinstance(baseline, dict):
        return None
    sha = baseline.get("base_git_sha")
    return str(sha).strip() if sha else None


def _iter_changed_files(change_dir: Path, project_root: Path, status_filter=None):
    """列出 change 期间的改动文件：baseline 与**工作区**的差异。

    返回 (files, reason)：files 为 [(status, rel_path)]，reason 非空表示无法执行。

    ⚠️ 用 `git diff <sha>`（不带 `..HEAD`）而非 `git diff <sha>..HEAD` ——
    前者对比 baseline 与工作区，**包含未提交改动**。BUILD 阶段改动都在工作区，
    用 `..HEAD` 会让自查恒报「0 个改动文件」，等于范围锁在 BUILD 期失效
    （实测 2026-10-28：本 change 自查时闸2 显示 0 个改动文件）。
    未跟踪的新文件由 `git status --porcelain` 补充（`git diff` 看不到它们）。
    """
    import subprocess

    sha = _load_baseline_sha(change_dir)
    if not sha:
        return [], "无法确定 change 起点（.fstdd.yaml 缺 baseline.base_git_sha）"
    try:
        r = subprocess.run(
            ["git", "diff", "--name-status", sha],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=20,
        )
    except Exception as exc:  # noqa: BLE001
        return [], f"git diff 执行失败（{type(exc).__name__}）"
    if r.returncode != 0:
        return [], f"git diff 返回 {r.returncode}（baseline {sha[:8]} 可能已不可达）"

    files = []
    for line in (r.stdout or "").splitlines():
        parts = line.split("\t")
        if len(parts) < 2:
            continue
        status = parts[0].strip()
        path = parts[-1].strip().replace("\\", "/")
        if not status or not path:
            continue
        if status_filter and status[0] not in status_filter:
            continue
        files.append((status, path))

    # 补充未跟踪的新文件（git diff 不显示 untracked）
    try:
        r2 = subprocess.run(
            ["git", "status", "--porcelain", "--untracked-files=all"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=20,
        )
        if r2.returncode == 0:
            seen = {p for _s, p in files}
            for line in (r2.stdout or "").splitlines():
                if not line.startswith("?? "):
                    continue
                path = line[3:].strip().replace("\\", "/")
                if not path or path in seen:
                    continue
                if status_filter and "A" not in status_filter:
                    continue
                files.append(("A", path))
    except Exception:  # noqa: BLE001
        pass

    return files, ""


def _sanitize_scope_patterns(patterns):
    """剔除含 `..` 的 scope pattern（输入层拒绝，EXP-2026-0027）。

    返回 (cleaned, dropped)。
    """
    cleaned, dropped = [], []
    for raw in patterns:
        s = str(raw).strip()
        if not s:
            continue
        parts = Path(s.replace("\\", "/")).parts
        if ".." in parts or s in (".", ".."):
            dropped.append(s)
            continue
        cleaned.append(s)
    return cleaned, dropped


def _is_scope_too_broad(patterns):
    """返回过宽的 pattern 列表（声明了整个根目录 ⇒ 范围锁失效）。"""
    broad = []
    for raw in patterns:
        s = str(raw).strip()
        norm = s.rstrip("/")
        if s in ("", ".") or norm in ("", "."):
            broad.append(s or "(空串)")
        elif norm in _BROAD_SCOPE_ROOTS:
            broad.append(s)
    return broad


def _is_scope_exempt(rel_path: str) -> bool:
    """流程产出物豁免：即使不在 scope.paths 内也不算蔓延。"""
    p = str(rel_path).replace("\\", "/")
    if p in SCOPE_EXEMPT_EXACT:
        return True
    return any(p.startswith(pref) for pref in SCOPE_EXEMPT_PREFIXES)


@_register_check
def check_scope_creep(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(b) 范围蔓延：基于 change 自己声明的 scope.paths 与实际 diff 逐文件比对。

    严格度按「是否声明 scope.paths」自然分界（不引入时间基准）：
    - 已声明 + 越界  -> FAIL
    - 已声明 + 在范围内 -> PASS
    - 未声明          -> WARN（老 change 不爆红）
    """
    from .guard import _load_change_scope, _is_in_change_scope

    raw_patterns = _load_change_scope(change_dir)
    if not raw_patterns:
        return (
            "WARN",
            "(b) 范围锁未生效：本 change 未声明 scope.paths —— 在 "
            "canonical/proposals/*.yaml 加 `scope: {paths: [...]}` 即可启用严格检查",
        )

    patterns, dropped = _sanitize_scope_patterns(raw_patterns)
    notes = []
    if dropped:
        notes.append(f"已剔除含 .. 的 pattern {len(dropped)} 条（{'、'.join(dropped[:3])}）")
    if not patterns:
        msg = "(b) 范围锁未生效：scope.paths 全部无效"
        return ("WARN", msg + ("；" + "；".join(notes) if notes else ""))

    broad = _is_scope_too_broad(patterns)
    if broad:
        notes.append(f"scope 过宽（{'、'.join(broad)}）—— 建议收窄到具体文件或子目录")

    changed, reason = _iter_changed_files(change_dir, project_root)
    if reason:
        msg = f"(b) 无法执行范围检查：{reason}"
        return ("WARN", msg + ("；" + "；".join(notes) if notes else ""))

    out_of_scope = []
    for _status, path in changed:
        if _is_scope_exempt(path):
            continue
        if not _is_in_change_scope(project_root, path, patterns):
            out_of_scope.append(path)

    if out_of_scope:
        head = "、".join(out_of_scope[:5])
        more = f" 等 {len(out_of_scope)} 个" if len(out_of_scope) > 5 else ""
        msg = (
            f"(b) 范围蔓延：{len(out_of_scope)} 个文件不在本 change 声明范围内"
            f"（{head}{more}）—— 若属本 change 请补进 scope.paths，否则移出本次改动"
        )
        return ("FAIL", msg + ("；" + "；".join(notes) if notes else ""))

    msg = (
        f"(b) 文件变更在声明范围内（{len(patterns)} 条 scope.paths，"
        f"{len(changed)} 个改动文件）"
    )
    return ("PASS", msg + ("；" + "；".join(notes) if notes else ""))


# ── DELIVER 冻结 / 断言核实 / backlog（anti-drift-gates）──────────

# 收尾阶段禁止新增的路径前缀：新增功能/测试属范围膨胀（形态 C）
DELIVER_FREEZE_PREFIXES = ("upstream/fstdd/", "upstream/tests/")

# 逃生阀环境变量：设了非空理由即放行（留痕优先于硬拦）
ALLOW_LATE_ENV = "FSTDD_ALLOW_LATE_CHANGE"

# commit message 里的版本号形态（严格三段式，避免误吃 1.2 或 2026-10-28）
_VERSION_IN_MSG_RE = re.compile(r"\bv(\d+\.\d+\.\d+)\b")


def _load_change_state(change_dir: Path) -> dict:
    """读 change 的 .fstdd.yaml；任何失败返回 {}（调用方按 SKIP 处理）。"""
    state_file = change_dir / ".fstdd.yaml"
    if not state_file.exists():
        return {}
    try:
        import yaml as _yaml
        data = _yaml.safe_load(state_file.read_text(encoding="utf-8")) or {}
    except Exception:  # noqa: BLE001
        return {}
    return data if isinstance(data, dict) else {}


@_register_check
def check_deliver_freeze(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(n) DELIVER 冻结：收尾阶段禁止新增源文件 / 测试文件。

    判据：`current_phase == deliver` 且 `phases.build.status == completed` 时，
    baseline..HEAD 的 **A（新增）** 状态文件落在 upstream/fstdd/ 或 upstream/tests/
    ⇒ FAIL。`.fstdd/` 与 `docs/` 属归档产出物，天然不在前缀内。
    逃生阀：环境变量 `FSTDD_ALLOW_LATE_CHANGE='理由'` 放行并回显理由。
    """
    state = _load_change_state(change_dir)
    if not state:
        return ("SKIP", "(n) .fstdd.yaml 缺失，跳过冻结检查")

    phase = state.get("current_phase")
    build_status = ((state.get("phases") or {}).get("build") or {}).get("status")
    if phase != "deliver" or build_status != "completed":
        return (
            "SKIP",
            f"(n) 未处于 deliver+build完成（当前 {phase}/{build_status}），冻结不适用",
        )

    changed, reason = _iter_changed_files(change_dir, project_root, status_filter="A")
    if reason:
        return ("WARN", f"(n) 无法执行冻结检查：{reason}")

    late = [
        p for _st, p in changed
        if any(p.startswith(pre) for pre in DELIVER_FREEZE_PREFIXES)
    ]
    allow = (os.environ.get(ALLOW_LATE_ENV) or "").strip()

    if late and not allow:
        head = "、".join(late[:5])
        more = f" 等 {len(late)} 个" if len(late) > 5 else ""
        return ("FAIL", (
            f"(n) DELIVER 冻结：收尾阶段新增了 {len(late)} 个源/测试文件"
            f"（{head}{more}）—— 收尾不应新增功能；确需新增请设 "
            f"{ALLOW_LATE_ENV}='理由' 显式放行"
        ))
    if late and allow:
        return ("PASS", f"(n) DELIVER 冻结已放行（理由：{allow}），新增 {len(late)} 个文件")
    return ("PASS", "(n) DELIVER 相位无新增源/测试文件")


@_register_check
def check_claims(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(o) 断言核实：commit message 里的版本号须与 version.yaml 一致。

    这是「形态 A 无证据断言」唯一可机器验证的部分 —— 本仓 2026-10-27 实测：
    commit 写「v3.4.0 增量」而 3.4.0 早已发布，无任何检查发现该矛盾。
    """
    version_file = project_root / ".fstdd" / "version.yaml"
    if not version_file.exists():
        return ("SKIP", "(o) .fstdd/version.yaml 缺失")
    try:
        import yaml as _yaml
        vdata = _yaml.safe_load(version_file.read_text(encoding="utf-8")) or {}
    except Exception:  # noqa: BLE001
        return ("SKIP", "(o) version.yaml 解析失败")
    actual = str((vdata or {}).get("fstdd_version") or "").strip()
    if not actual:
        return ("SKIP", "(o) version.yaml 缺 fstdd_version")

    sha = _load_baseline_sha(change_dir)
    if not sha:
        return ("WARN", "(o) 无法确定 change 起点（缺 baseline），断言核实跳过")

    import subprocess
    try:
        # 只扫 **subject**（标题行），不扫 body。
        # 理由：body 里常引用历史版本（如「修复 v3.4.0 引入的问题」「本仓 v3.3.6 记为已知缺陷」），
        # 那是**引用**不是**断言**；标题才是「这条 commit 声称自己做了什么」。
        # 实测 2026-10-28：扫全文时本 change 的 commit body 引用了 v3.3.6 / v3.4.0
        # ⇒ 假报「版本号矛盾」。
        r = subprocess.run(
            ["git", "log", "--format=%s", f"{sha}..HEAD"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=20,
        )
    except Exception as exc:  # noqa: BLE001
        return ("WARN", f"(o) git log 执行失败（{type(exc).__name__}）")
    if r.returncode != 0:
        return ("WARN", f"(o) git log 返回 {r.returncode}")

    found = set(_VERSION_IN_MSG_RE.findall(r.stdout or ""))
    # 排除「已有 tag 的历史版本」：提到已发布版本属引用，不构成矛盾
    try:
        tag_out = subprocess.run(
            ["git", "tag", "--list", "fstdd-v*"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=20,
        ).stdout or ""
        tagged = {
            m.group(1)
            for m in (re.match(r"^fstdd-v(\d+\.\d+\.\d+)$", t.strip()) for t in tag_out.splitlines())
            if m
        }
    except Exception:  # noqa: BLE001
        tagged = set()
    found = {v for v in found if v not in tagged}

    mismatched = sorted(v for v in found if v != actual)
    if mismatched:
        shown = "、".join("v" + v for v in mismatched)
        return ("FAIL", (
            f"(o) 断言核实失败：commit message 出现 {shown}，"
            f"而 version.yaml 的 fstdd_version 是 {actual}"
            f" —— 版本号须与实际一致（改 message 或升版）"
        ))
    if found:
        return ("PASS", f"(o) commit message 版本号一致（v{actual}，{len(found)} 种）")
    return ("PASS", "(o) commit message 未出现版本号，无需核实")


@_register_check
def check_backlog_open(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(p) 候选池未闭合项：DELIVER 时提示 `.fstdd/backlog.md` 还有多少债。

    只 WARN 不阻断 —— 阻断会逼人为了过门禁而乱勾，反而毁掉候选池的可信度。
    """
    state = _load_change_state(change_dir)
    phase = state.get("current_phase")
    if phase != "deliver":
        return ("SKIP", f"(p) 未处于 deliver（当前 {phase}），backlog 检查不适用")

    backlog = project_root / ".fstdd" / "backlog.md"
    if not backlog.exists():
        return ("PASS", "(p) 无 .fstdd/backlog.md（尚未建候选池）")

    try:
        text = backlog.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        return ("SKIP", f"(p) backlog.md 不可读（{type(exc).__name__}）")

    total = 0
    mine = 0
    tag = f"[{change_dir.name}]"
    for line in text.splitlines():
        s = line.strip()
        if s.startswith("- [ ]"):
            total += 1
            if tag in s:
                mine += 1

    if total == 0:
        return ("PASS", "(p) backlog 无未处理项")
    return ("WARN", (
        f"(p) backlog 有 {total} 项未处理（本 change 引入 {mine} 项、"
        f"历史遗留 {total - mine} 项）—— 建议转入下一轮迭代，不阻断"
    ))


@_register_check
def check_coverage_vacuum(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(j) Check test coverage against threshold."""
    cov_path = project_root / "coverage.json"
    if not cov_path.exists():
        return ("SKIP", "(j) 无 coverage.json，跳过覆盖检查")

    try:
        cov_data = json.loads(cov_path.read_text(encoding="utf-8"))
        pct = cov_data.get("summary", {}).get("percent_covered", cov_data.get("totals", {}).get("percent_covered"))
        if pct is None:
            return ("SKIP", "(j) coverage.json 无 percent_covered 字段")
    except Exception:
        return ("SKIP", "(j) coverage.json 解析失败")

    # Read threshold from quality.yaml
    from ..utils import read_config
    config = read_config(project_root)
    threshold = config.get("quality", {}).get("coverage_threshold", 80)

    if pct >= threshold:
        return ("PASS", f"(j) 覆盖率 {pct:.1f}% >= {threshold}%")
    return ("FAIL", f"(j) 覆盖率不足: {pct:.1f}% < {threshold}%")


@_register_check
def check_contract_gap(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(k) Check contract consistency across capabilities."""
    specs_dir = change_dir / "specs"
    if not specs_dir.exists() or len(list(specs_dir.iterdir())) < 2:
        return ("SKIP", "(k) 少于 2 个 capability，跳过契约检查")

    # Build a map: capability_name -> set of defined fields/entities
    cap_fields = {}
    for cap_dir in specs_dir.iterdir():
        if not cap_dir.is_dir():
            continue
        spec_file = cap_dir / "spec.md"
        if not spec_file.exists():
            continue
        content = spec_file.read_text(encoding="utf-8")
        cap_name = cap_dir.name
        # Extract field definitions: words after "SHALL" patterns, Requirement names
        fields = set(re.findall(r"SHALL\s+(\w+)", content))
        # Also capture Requirement names
        reqs = set(re.findall(r"## Requirement:\s*(.+)", content))
        cap_fields[cap_name] = fields | reqs

    if len(cap_fields) < 2:
        return ("SKIP", "(k) 有效的 capability spec 不足，跳过契约检查")

    # Check cross-references: "GIVEN.*from <capability>" pattern
    gaps = []
    for cap_name, defined_fields in cap_fields.items():
        spec_file = specs_dir / cap_name / "spec.md"
        content = spec_file.read_text(encoding="utf-8")
        refs = re.findall(r"GIVEN.*from\s+(\S+)", content)
        for ref_cap in refs:
            ref_cap_clean = ref_cap.rstrip(".")
            if ref_cap_clean in cap_fields:
                # Check if referenced fields exist in the target capability
                ref_content = (specs_dir / ref_cap_clean / "spec.md").read_text(encoding="utf-8")
                # Extract field names referenced from target
                ref_fields = set(re.findall(r"GIVEN.*from\s+" + re.escape(ref_cap_clean) + r".*?(\w+)", content))
                target_fields = cap_fields[ref_cap_clean]
                missing = ref_fields - target_fields
                if missing and ref_fields:
                    gaps.append(f"{cap_name} -> {ref_cap_clean}: 引用未定义字段")

    if gaps:
        return ("FAIL", f"(k) 契约断层: {'; '.join(gaps[:3])}")
    return ("PASS", f"(k) 契约一致 ({len(cap_fields)} capabilities)")


def _scan_gate_evidence_tags(change_dir: Path):
    """返回 evidence 缺 [F] 标签的 Gate 名列表（已确认的才检查）。"""
    from ..utils import has_fact_tag

    state = _load_change_state(change_dir)
    phases = state.get("phases") or {}
    missing = []
    for label, key in (("Gate 1", "understand"), ("Gate 2", "spec"), ("Gate 3", "build")):
        phase_data = phases.get(key) or {}
        if not phase_data.get("confirmed_at"):
            continue
        if not has_fact_tag(phase_data.get("confirmed_evidence") or ""):
            missing.append(label)
    return missing


def cmd_check_drift(args: argparse.Namespace) -> None:
    """`ci check-drift` —— 反漂移三闸聚合报告。

    闸1 断言证据：commit 版本号核实 + Gate evidence 是否带事实标签
    闸2 范围锁：实际 diff 与 scope.paths 比对
    闸3 收尾冻结：deliver 相位禁新增源文件 + backlog 未闭合项

    退出码：任一闸 FAIL ⇒ 1；`--strict` 时任一闸 WARN 亦 ⇒ 1；否则 0。
    """
    from ..finder import find_change_dir

    project_root = Path.cwd()
    change_dir = find_change_dir(getattr(args, "name", None), project_root, include_archive=True)
    if change_dir is None:
        print(f" 找不到 change: {getattr(args, 'name', None) or '(无)'}")
        sys.exit(1)

    strict = bool(getattr(args, "strict", False))
    as_json = bool(getattr(args, "json", False))

    # ── 闸1：断言证据 ──
    claims_status, claims_msg = check_claims(change_dir, project_root)
    gate1 = [{"name": "claims", "status": claims_status, "message": claims_msg}]
    missing_tags = _scan_gate_evidence_tags(change_dir)
    if missing_tags:
        gate1.append({
            "name": "evidence-tag",
            "status": "WARN",
            "message": f"以下 Gate 的 evidence 缺 [F] 事实标签：{'、'.join(missing_tags)}",
        })

    # ── 闸2：范围锁 ──
    scope_status, scope_msg = check_scope_creep(change_dir, project_root)
    if strict and scope_status == "WARN":
        scope_status = "FAIL"
        scope_msg += "（--strict：WARN 升格为 FAIL）"
    gate2 = [{"name": "scope", "status": scope_status, "message": scope_msg}]

    # ── 闸3：收尾冻结 ──
    freeze_status, freeze_msg = check_deliver_freeze(change_dir, project_root)
    backlog_status, backlog_msg = check_backlog_open(change_dir, project_root)
    gate3 = [
        {"name": "deliver-freeze", "status": freeze_status, "message": freeze_msg},
        {"name": "backlog", "status": backlog_status, "message": backlog_msg},
    ]

    gates = [("闸1 断言证据", gate1), ("闸2 范围锁", gate2), ("闸3 收尾冻结", gate3)]

    def _gate_status(items):
        if any(i["status"] == "FAIL" for i in items):
            return "FAIL"
        if any(i["status"] == "WARN" for i in items):
            return "WARN"
        if all(i["status"] == "SKIP" for i in items):
            return "SKIP"
        return "PASS"

    summary = [(label, _gate_status(items), items) for label, items in gates]

    if as_json:
        print(json.dumps(
            {
                "change": change_dir.name,
                "strict": strict,
                "gates": [
                    {
                        "gate": label,
                        "status": st,
                        "items": items,
                    }
                    for label, st, items in summary
                ],
            },
            ensure_ascii=False,
            indent=2,
        ))
    else:
        print()
        print("  FSTDD 反漂移三闸报告")
        print(f"  change: {change_dir.name}{'（strict）' if strict else ''}")
        print(f"  {'─' * 56}")
        symbol = {"PASS": "✓", "FAIL": "✗", "WARN": "⚠", "SKIP": "→"}
        for label, st, items in summary:
            print(f"  {symbol.get(st, '?')} {label}: {st}")
            for item in items:
                print(f"      [{item['status']}] {item['message']}")
        print(f"  {'─' * 56}")

    has_fail = any(st == "FAIL" for _l, st, _i in summary)
    has_warn = any(st == "WARN" for _l, st, _i in summary)
    if has_fail or (strict and has_warn):
        sys.exit(1)


def cmd_ci(args: argparse.Namespace) -> None:
    from ..utils import get_logger
    get_logger()

    project_root = Path.cwd()

    subcommand = args.subcommand if getattr(args, "subcommand", None) else "init"

    if subcommand == "init":
        config = _read_quality_config(project_root)
        _cmd_init(args, project_root, config)
    elif subcommand in ("generate", "gen"):
        config = _read_quality_config(project_root)
        _cmd_generate(args, project_root, config)
    elif subcommand == "check-failures":
        _cmd_check_failures(args, project_root)
    elif subcommand in ("check-scope", "check-coverage", "check-contracts"):
        _run_single_check(args, project_root, subcommand)
    elif subcommand == "check-drift":
        cmd_check_drift(args)
    else:
        print(f" 未知子命令: {subcommand}")
        print(" 可用: init, generate, check-failures, check-scope, check-coverage, "
              "check-contracts, check-drift")
        sys.exit(1)


def _run_single_check(args: argparse.Namespace, project_root: Path, subcommand: str) -> None:
    """Run a single named check and report result."""
    from ..finder import find_change_dir

    change_dir = find_change_dir(getattr(args, "name", None), project_root, include_archive=True)
    if change_dir is None:
        print(f" 找不到 change: {getattr(args, 'name', None) or '(无)'}")
        sys.exit(1)

    check_map = {
        "check-scope": check_scope_creep,
        "check-coverage": check_coverage_vacuum,
        "check-contracts": check_contract_gap,
    }
    fn = check_map[subcommand]
    status, message = fn(change_dir, project_root)
    symbol = {"PASS": "✓", "FAIL": "✗", "WARN": "⚠", "SKIP": "→"}
    print(f"  {symbol.get(status, '?')} [{status}] {message}")
    if status == "FAIL":
        sys.exit(1)


# ── V2.7 复盘新增: TC 计划 vs 实际测试对账 ─────────────────

@_register_check
def check_tc_implementation_coverage(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """Check that test-plan TC-IDs have corresponding test implementations.

    This is the critical check that would have caught the V2.7 development failure:
    30 planned TCs had zero corresponding test functions.

    EXP-2026-0067：planned TC 只按**定义点**提取（走 _tcid_definition_points），
    不再用全文 `_TC_ANY_RE` —— 否则 test-plan 里**引用**的他人 TC-ID（回归矩阵 /
    证据表 / 案例标题等）会被误算进 planned，把覆盖率稀释并漏检真正的缺口。
    """
    test_plan = change_dir / "test-plan.md"
    if not test_plan.exists():
        return ("SKIP", "test-plan.md 不存在，跳过 TC 实现覆盖检查")

    content = test_plan.read_text(encoding="utf-8")
    # EXP-2026-0067：优先按定义点提取；无定义点时回退全文（旧格式兼容）
    def_points = _tcid_definition_points(content)
    if def_points:
        planned_tcs = set(def_points)
    else:
        planned_tcs = set(re.findall(r"(TC-[A-Z]+-\d{3})", content))
    if not planned_tcs:
        return ("SKIP", "test-plan.md 中未找到 TC-ID")

    # Search for TC-IDs in test files
    # REQ-CTR-001：经 iter_test_files 单一事实源扫描（test_*.py + test-*.py），
    # 不再直接 rglob("test_*.py")——后者对连字符命名结构性失明（下游多层次agent
    # 的 EXP-2026-0001 类假红；本仓同名编号为 Guard 阶段门，非此语义）。
    from ..utils import iter_test_files
    # anti-drift-gates（2026-10-28）：同时扫仓库根 `tests/` 与 `upstream/tests/`。
    # 原实现只看 `<root>/tests` ⇒ upstream 侧 change 的 TC 覆盖恒报 0/N
    # （本仓 v3.3.6 已记为已知缺陷；本轮实测 0/24 复现，故一并修）。
    test_dirs = [project_root / "tests", project_root / "upstream" / "tests"]
    existing_dirs = [d for d in test_dirs if d.is_dir()]
    if not existing_dirs:
        return ("SKIP", "tests/ 与 upstream/tests/ 都不存在，跳过 TC 实现覆盖检查")

    implemented_tcs = set()
    for tests_dir in existing_dirs:
        for test_file in iter_test_files(tests_dir):
            file_content = test_file.read_text(encoding="utf-8")
            for tc_id in planned_tcs:
                if tc_id in file_content:
                    implemented_tcs.add(tc_id)

    missing = planned_tcs - implemented_tcs
    coverage_pct = len(implemented_tcs) / len(planned_tcs) * 100 if planned_tcs else 100

    if not missing:
        return ("PASS", f"TC 实现覆盖: {len(implemented_tcs)}/{len(planned_tcs)} (100%)")

    if coverage_pct < 50:
        return ("FAIL", f"TC 实现覆盖严重不足: {len(implemented_tcs)}/{len(planned_tcs)} ({coverage_pct:.0f}%)。缺失: {', '.join(sorted(missing)[:5])}{'...' if len(missing) > 5 else ''}")

    return ("WARN", f"TC 实现覆盖: {len(implemented_tcs)}/{len(planned_tcs)} ({coverage_pct:.0f}%)。缺失: {', '.join(sorted(missing)[:5])}{'...' if len(missing) > 5 else ''}")


@_register_check
def check_anchoring_missing(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """(l) Check critical Change has sufficient anchoring level (V2.7)."""
    import yaml as _yaml
    # Check for canonical proposal
    canon_file = project_root / ".fstdd" / "canonical" / "proposals" / f"{change_dir.name}.yaml"
    if not canon_file.exists():
        return ("SKIP", "(l) canonical proposal not found — cannot check anchoring")

    try:
        data = _yaml.safe_load(canon_file.read_text(encoding="utf-8"))
    except Exception:
        return ("SKIP", "(l) canonical proposal parse failed")

    critical = data.get("critical", {})
    if not critical.get("is_critical", False):
        return ("PASS", "(l) Non-critical change — anchoring not required")

    risk = critical.get("risk_assessment", {})
    required = "L1"
    if risk.get("financial"):
        required = "L4"
    elif risk.get("safety_critical"):
        required = "L3"
    elif risk.get("cross_system"):
        required = "L2"

    current = data.get("anchoring", {}).get("level", "L1")
    level_num = {"L1": 1, "L2": 2, "L3": 3, "L4": 4}

    if level_num.get(current, 1) < level_num.get(required, 1):
        return ("FAIL", f"(l) 锚定等级不足：当前 {current}，最低要求 {required}")
    return ("PASS", f"(l) Anchoring: {current} >= {required}")


@_register_check
def check_slice_completion(change_dir: Path, project_root: Path) -> tuple[str, str]:
    """Check that all slices marked 'done' have evidence (V2.7 post-mortem P4-3)."""
    stdd_yaml = change_dir / ".fstdd.yaml"
    if not stdd_yaml.exists():
        return ("SKIP", ".fstdd.yaml 不存在")

    import yaml as _yaml
    state = _yaml.safe_load(stdd_yaml.read_text(encoding="utf-8")) or {}
    # V3.0.5: canonical key is phases.build.slices_completed; tolerate legacy phase4.
    slices = (state.get("phases", {}).get("build", {}).get("slices_completed")
              or state.get("phase4", {}).get("slices_completed", {}))
    if not slices:
        return ("SKIP", "无切片完成记录")

    unverified = []
    for slice_id, info in slices.items():
        if info.get("status") == "done":
            tc_cov = info.get("tc_coverage", "N/A")
            new_tests = info.get("new_tests", 0)
            verified_at = info.get("verified_at", "")
            if not verified_at or new_tests == 0:
                unverified.append(f"Slice {slice_id} (new_tests={new_tests}, verified_at={'set' if verified_at else 'missing'})")

    if unverified:
        return ("WARN", f"以下切片标记为 done 但缺少验证证据: {'; '.join(unverified)}")

    return ("PASS", f"{len(slices)} 个切片均有验证证据")


# ── V2.8: pass@k verification ──────────────────────────────

def run_pass_k(test_command: str, k: int = 3) -> dict:
    """Run tests k times and compute pass@k metrics.

    Returns dict with: pass_count, total, pass_at_1, pass_at_k, details
    """
    import subprocess
    results = []
    for i in range(k):
        result = subprocess.run(test_command, shell=True, capture_output=True, text=True)
        results.append(result.returncode == 0)

    return {
        "pass_count": sum(results),
        "total": k,
        "pass_at_1": 1.0 if results[0] else 0.0,
        "pass_at_k": sum(results) / k if k > 0 else 0.0,
        "details": results,
    }


def check_passk_ambiguity(pass_at_1: float, pass_at_k: float, k: int) -> str | None:
    """Detect spec ambiguity: pass@1 low but pass@k high.

    Returns warning message if ambiguity detected, None otherwise.
    """
    if k < 3:
        return None
    if pass_at_1 < 0.5 and pass_at_k > 0.8:
        return (f"⚠️  Spec 可能存在歧义 — pass@1={pass_at_1:.0%} 但 pass@{k}={pass_at_k:.0%}。"
                f"建议在 Phase 2 中提升锚定等级。")
    return None
